describe('source hygiene of this repository', () => {
  const roots = ['src', 'tests', 'scripts'];
  const files = roots
    .flatMap(root =>
      readdirSync(path.join(repoRoot, root), { recursive: true, encoding: 'utf8' })
        .filter(name => name.endsWith('.ts'))
        .map(name => `${root}/${name.split(path.sep).join('/')}`),
    )

test('criteria 5, 6, 8: no .ts file under src/, tests/ or scripts/ has a raw invisible or control character', () => {
  const problems: string[] = [];
  for (const file of files) {
    let bytes: Uint8Array;
    try {
      bytes = readFileSync(path.join(repoRoot, file));
    } catch (error) {
      // A file that cannot be read is its own problem, not an encoding problem
      // (Qodo local review finding 7cb5aca3).
      const code = error instanceof Error && 'code' in error ? String(error.code) : 'unknown error';
      problems.push(`${file}: cannot be read (${code})`);
      continue;
    }
    problems.push(...sourceProblems(file, bytes));
  }
  assert.deepEqual(problems, [], `\n${problems.join('\n')}\n`);

/**
 * Formats one finding as a single line: `<path>:<line>:<column> raw U+XXXX, write <escape>`.
 *
 * Input: the file's path as it should be shown (relative, forward slashes) and a finding from
 * `findRawInvisible`. Output: the line, without a trailing newline. The path is printed as
 * given. Failure: none.
 */
export function describeRawInvisible(file: string, hit: RawInvisible): string {
  return `${file}:${hit.line}:${hit.column} raw U+${hex(hit.codePoint).padStart(4, '0')}, write ${hit.escape}`;

export function sourceProblems(file: string, bytes: Uint8Array): string[] {
  let text: string;
  try {
    text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(bytes);
  } catch {
    return [`${file}: not valid UTF-8`];
  }
  return findRawInvisible(text).map(hit => describeRawInvisible(file, hit));
